test('watermark controls repeat editable text behind every page, preserve source and remove with one undo',async({page})=>{
 const session=createDocumentSession(openWordDocument(createWordDocument({documentId:'watermark-ui',pageSetup:{unit:'pt',width:300,height:240,margins:{top:24,right:24,bottom:24,left:24}}}),{kind:'document'}));session.commit(session.prepare({protocolVersion:1,documentId:'watermark-ui',baseRevision:0,operations:[{op:'replaceFragment',nodeId:'section-root-1',html:'<p style="line-height:16pt;margin:0">'+Array.from({length:40},(_,index)=>'LINE-'+index).join('<br>')+'</p>'}]}));await mount(page,session.serialize(),'edit');const frame=page.frameLocator('iframe');await frame.locator('[data-office-editor] p').first().click();await page.evaluate(()=>(window.paginationHost.view as import('@doffi/editor').DocumentTextEditor).execute({type:'word',action:'watermark'}));await page.getByLabel('水印文字',{exact:true}).fill('CONFIDENTIAL');await page.getByLabel('水印字号（磅）',{exact:true}).fill('24');await page.getByRole('button',{name:'应用文字水印',exact:true}).click();const pages=(await page.evaluate(()=>window.paginationHost.layout())).pages.length,watermarks=frame.locator('.sdk-paper > [data-sdk-word-story-anchor]');await expect(watermarks).toHaveCount(pages);await expect(watermarks.first()).toContainText('CONFIDENTIAL');const positions=await frame.locator('body').evaluate(body=>[...body.querySelectorAll('.sdk-paper > [data-sdk-word-story-anchor]')].map(node=>{const parent=node.parentElement!.getBoundingClientRect(),rect=node.getBoundingClientRect();return{x:(rect.left+rect.width/2-parent.left)*.75,y:(rect.top+rect.height/2-parent.top)*.75};}));for(const position of positions){expect(position.x).toBeCloseTo(150,0);expect(position.y).toBeCloseTo(120,0);}expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().html)).not.toMatch(/sdk-word-story-anchor|sdk-word-drawing-text|position:absolute/);await page.getByRole('button',{name:'移除水印',exact:true}).click();await expect(watermarks).toHaveCount(0);await page.evaluate(()=>window.paginationHost.session!.undo());await expect(watermarks).toHaveCount(pages);expect(await page.evaluate(()=>window.paginationHost.errors)).toEqual([]);
 const files=await page.evaluate(()=>[...window.paginationHost.session!.serialize()].map(([path,bytes])=>[path,[...bytes]]as[string,number[]]));await page.evaluate(entries=>window.paginationHost.mount(entries,'preview'),files);expect(await page.evaluate(()=>(window.paginationHost.view as import('@doffi/editor').DocumentPreview).printDocument().querySelectorAll('.sdk-print-page [data-sdk-word-story-anchor]').length)).toBe(pages);
});
test('fixed table row heights clip long source text, avoid phantom pages and edit height rules with shared undo',async({page})=>{
 const session=createDocumentSession(openWordDocument(createWordDocument({documentId:'fixed-rows',pageSetup:{unit:'pt',width:300,height:240,margins:{top:24,right:24,bottom:24,left:24}}}),{kind:'document'}));session.commit(session.prepare({protocolVersion:1,documentId:'fixed-rows',baseRevision:0,operations:[{op:'insertWordTable',nodeId:'paragraph-1',position:'after',rows:2,columns:2,width:240}]}));const table=session.snapshot().metadata.word!.tables[0]!.nodeId,text=Array.from({length:40},(_,index)=>'LONG-'+index).join('\n');session.commit(session.prepare({protocolVersion:1,documentId:'fixed-rows',baseRevision:1,operations:[{op:'editWordTable',nodeId:table,change:{kind:'setCells',row:0,column:0,values:[[text,'A'],['B','C']]}},{op:'editWordTable',nodeId:table,change:{kind:'resize',rowHeights:[24,24]}},{op:'formatWordTable',nodeId:table,rowHeightRule:'exact'}]}));await mount(page,session.serialize(),'edit');const frame=page.frameLocator('iframe');expect(await frame.locator('tr').first().evaluate(row=>row.getBoundingClientRect().height*.75)).toBeCloseTo(24,0);expect((await page.evaluate(()=>window.paginationHost.layout())).pages).toHaveLength(1);expect(await frame.locator('.sdk-word-row-clip').count()).toBe(4);expect(await page.evaluate(()=>window.paginationHost.session!.getNode(window.paginationHost.session!.snapshot().metadata.word!.tables[0]!.nodeId)!.text)).toContain(text);await frame.locator('td').first().click();await page.evaluate(()=>(window.paginationHost.view as import('@doffi/editor').DocumentTextEditor).execute({type:'word',action:'tableSettings'}));await page.getByLabel('行高规则',{exact:true}).selectOption('atLeast');await page.getByRole('button',{name:'设置行高',exact:true}).click();await expect(frame.locator('.sdk-word-row-clip')).toHaveCount(0);expect((await page.evaluate(()=>window.paginationHost.layout())).pages.length).toBeGreaterThan(1);await page.evaluate(()=>window.paginationHost.session!.undo());await expect(frame.locator('.sdk-word-row-clip')).toHaveCount(4);expect((await page.evaluate(()=>window.paginationHost.layout())).pages).toHaveLength(1);expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().html)).not.toMatch(/sdk-word-row-clip|overflow:hidden|flex-direction/);expect(await page.evaluate(()=>window.paginationHost.errors)).toEqual([]);
});
test('table border guides drag columns and one row through tracked atomic undo while Escape cancels the gesture',async({page})=>{
 const session=createDocumentSession(openWordDocument(createWordDocument({documentId:'table-drag'}),{kind:'document'}));session.commit(session.prepare({protocolVersion:1,documentId:'table-drag',baseRevision:0,operations:[{op:'insertWordTable',nodeId:'paragraph-1',position:'after',rows:2,columns:2,width:240},{op:'setWordReview',nodeId:'document-root',trackChanges:true,author:'甲'}]}));const tableId=session.snapshot().metadata.word!.tables[0]!.nodeId;await mount(page,session.serialize(),'edit');const frame=page.frameLocator('iframe'),cell=frame.locator('td').first();await cell.hover();const column=frame.getByRole('button',{name:'调整第 1 列宽度',exact:true}),handle=await column.boundingBox(),width=await frame.locator('table').evaluate(table=>table.getBoundingClientRect().width);await page.mouse.move(handle!.x+4,handle!.y+12);await page.mouse.down();await page.mouse.move(handle!.x+44,handle!.y+12,{steps:4});await page.mouse.up();const resized=await page.evaluate(id=>window.paginationHost.session!.snapshot().metadata.word!.tables.find(table=>table.nodeId===id)!.grid,tableId);expect(resized[0]).toBeCloseTo(120+Math.round(40*240/width*4)/4);expect(resized[0]!+resized[1]!).toBe(240);expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.word!.revisions.some(item=>item.property==='tableGrid'))).toBe(true);await page.evaluate(()=>window.paginationHost.session!.undo());expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.word!.tables[0]!.grid)).toEqual([120,120]);
 await cell.hover();const row=frame.getByRole('button',{name:'调整第 1 行高度',exact:true}),rowHandle=await row.boundingBox();await page.mouse.move(rowHandle!.x+12,rowHandle!.y+4);await page.mouse.down();await page.mouse.move(rowHandle!.x+12,rowHandle!.y+24,{steps:3});await page.mouse.up();const result=await page.evaluate(()=>{const session=window.paginationHost.session!,snapshot=session.snapshot(),table=session.getNode(snapshot.metadata.word!.tables[0]!.nodeId)!,rows=table.childNodeIds.flatMap(id=>{const node=session.getNode(id)!;return node.tagName==='tr'?[node]:node.childNodeIds.map(id=>session.getNode(id)!);});return{snapshot,rows:rows.map(row=>row.attributes.style),errors:window.paginationHost.errors};});expect(result.snapshot.metadata.word!.revisions.filter(item=>item.property==='row')).toHaveLength(1);expect(result.rows[0]).toContain('height:');expect(result.rows[1]).toBeUndefined();expect(result.snapshot.html).not.toMatch(/sdk-table-resize|position:fixed/);expect(result.errors).toEqual([]);await page.evaluate(()=>window.paginationHost.session!.undo());
 await cell.hover();const cancelHandle=await frame.getByRole('button',{name:'调整第 1 列宽度',exact:true}).boundingBox();await page.mouse.move(cancelHandle!.x+4,cancelHandle!.y+12);await page.mouse.down();await page.mouse.move(cancelHandle!.x+24,cancelHandle!.y+12);await page.keyboard.press('Escape');await page.mouse.up();expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.word!.tables[0]!.grid)).toEqual([120,120]);expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.word!.revisions)).toEqual([]);
});
test('unequal text columns reflow to individual widths, keep exact second-column typing and expose reversible page controls',async({page})=>{
 const text='abcdefghij '.repeat(160),session=createDocumentSession(openWordDocument(createWordDocument({documentId:'unequal-columns',pageSetup:{unit:'pt',width:300,height:240,margins:{top:24,right:24,bottom:24,left:24}}}),{kind:'document'}));session.commit(session.prepare({protocolVersion:1,documentId:'unequal-columns',baseRevision:0,operations:[{op:'replaceFragment',nodeId:'section-root-1',html:'<p style="font-family:&quot;Liberation Mono&quot;;font-size:10pt;line-height:12pt;margin:0;background-color:#eeeeee;border:.5pt solid black">'+text+'</p>'},{op:'setWordSection',nodeId:'section-root-1',changes:{columns:{count:2,gap:24,widths:[72,156],spaces:[24,0],separator:true}}}]}));await mount(page,session.serialize(),'edit');const frame=page.frameLocator('iframe'),paragraph=frame.locator('[data-office-editor] p').first(),lines=await paragraph.evaluate(element=>{const walker=document.createTreeWalker(element,4),base=element.closest('.sdk-page-flow')!.getBoundingClientRect(),lines:{x:number;y:number;width:number}[]=[];for(let text=walker.nextNode();text;text=walker.nextNode()){const range=document.createRange();range.selectNodeContents(text);for(const rect of range.getClientRects())if(rect.width>.1&&rect.height>.1)lines.push({x:rect.left-base.left,y:rect.top-base.top,width:rect.width});}return lines;});expect(Math.max(...lines.filter(line=>line.x<100&&line.y<250).map(line=>line.width))).toBeLessThan(98);expect(Math.max(...lines.filter(line=>line.x>120&&line.y<250).map(line=>line.width))).toBeGreaterThan(150);
 await paragraph.evaluate(element=>{const walker=document.createTreeWalker(element,4),base=element.closest('.sdk-page-flow')!.getBoundingClientRect();for(let text=walker.nextNode();text;text=walker.nextNode()){const range=document.createRange();range.selectNodeContents(text);const rect=range.getBoundingClientRect();if(rect.left-base.left>120&&rect.top-base.top<250){range.setStart(text,0);range.collapse(true);const selection=document.getSelection()!;selection.removeAllRanges();selection.addRange(range);(element.closest('[data-office-editor]')as HTMLElement).focus();return;}}throw new Error('Missing wide-column text.');});await page.keyboard.insertText('EDIT');
 const current=await page.evaluate(()=>window.paginationHost.session!.getNode(window.paginationHost.session!.snapshot().metadata.sections![0]!.rootNodeId)!.text);expect(current.replace('EDIT','')).toBe(text);expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().html)).not.toMatch(/sdk-column-exclusion|shape-outside|position:relative/);await page.evaluate(()=>(window.paginationHost.view as import('@doffi/editor').DocumentTextEditor).execute({type:'word',action:'pageSettings'}));await page.getByLabel('等宽分栏',{exact:true}).uncheck();await page.getByLabel('各栏宽度（磅，以逗号分隔）',{exact:true}).fill('100,128');await page.getByLabel('各栏后间距（磅，以逗号分隔）',{exact:true}).fill('24,0');await page.getByRole('button',{name:'应用分栏',exact:true}).click();expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.sections![0]!.columns!.widths)).toEqual([100,128]);await page.evaluate(()=>window.paginationHost.session!.undo());expect(await page.evaluate(()=>window.paginationHost.session!.snapshot().metadata.sections![0]!.columns!.widths)).toEqual([72,156]);expect(await page.evaluate(()=>window.paginationHost.errors)).toEqual([]);
});
